def peak_index_in_mountain_array(arr):
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < arr[mid + 1]:
            lo = mid + 1                 # still climbing, peak is to the right
        else:
            hi = mid                      # already descending (or at peak)
    return lo

